.question-screen {
  --question-screen-art: url("data:image/png;base64,");
  display: grid;
  place-items: center;
  min-height: 100%;
  padding: clamp(12px, 4vh, 36px) 24px;
}

.question-screen__backdrop {
  position: absolute;
  z-index: -1;
  inset: 0;
  background-color: #101318;
  background-image:
    linear-gradient(110deg, rgba(9, 12, 17, 0.68), rgba(9, 12, 17, 0.42)),
    var(--question-screen-art);
  background-position: center;
  background-size: cover;
  transform: scale(1.02);
}

.question-screen::after {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: radial-gradient(ellipse at 50% 46%, transparent 12%, rgba(4, 6, 10, 0.32) 100%);
  content: "";
  pointer-events: none;
}

.question-panel {
  width: min(820px, 100%);
  max-height: 100%;
  overflow-y: auto;
  padding: clamp(24px, 3.5vw, 40px) clamp(24px, 6vw, 68px);
  border: 1px solid rgba(245, 242, 232, 0.28);
  border-radius: 2px;
  background: rgba(18, 21, 26, 0.58);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.2), inset 0 1px rgba(255, 255, 255, 0.08);
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
  animation: question-panel-arrive 0.7s ease-out both;
}

.question-header {
  padding-bottom: clamp(18px, 2.7vh, 26px);
  border-bottom: 1px solid rgba(245, 242, 232, 0.24);
}

.question-header__eyebrow {
  margin: 0 0 14px;
  color: rgba(239, 234, 221, 0.68);
  font-size: 10px;
  letter-spacing: 0.2em;
}

.question-header__eyebrow span {
  padding: 0 6px;
  color: rgba(239, 234, 221, 0.44);
}

.question-header h1 {
  margin: 0;
  color: #f3f0e9;
  font-size: clamp(25px, 3.2vw, 38px);
  font-weight: 400;
  letter-spacing: -0.07em;
  line-height: 1.3;
}

.question-header__description {
  margin: 10px 0 0;
  color: rgba(239, 234, 221, 0.7);
  font-size: clamp(13px, 1.5vw, 15px);
  letter-spacing: -0.035em;
}

.question-form {
  padding-top: clamp(18px, 3vh, 28px);
}

.question-block {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.question-block + .question-block {
  margin-top: clamp(24px, 3.2vh, 30px);
}

.question-block legend,
.question-block__legend {
  display: block;
  width: 100%;
  margin: 0;
  padding: 0;
  color: rgba(246, 243, 235, 0.91);
  font-size: clamp(14px, 1.7vw, 17px);
  font-weight: 400;
  letter-spacing: -0.04em;
}

.question-block__index {
  display: inline-block;
  margin-right: 12px;
  color: rgba(218, 210, 192, 0.62);
  font-size: 10px;
  letter-spacing: 0.12em;
  vertical-align: 2px;
}

.age-timeline {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 24px;
}

.age-timeline::before {
  position: absolute;
  top: 5px;
  right: 12.5%;
  left: 12.5%;
  height: 1px;
  background: rgba(238, 234, 224, 0.35);
  content: "";
}

.age-timeline__point {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 14px;
  min-width: 0;
  padding: 0 4px;
  border: 0;
  background: transparent;
  color: rgba(239, 234, 221, 0.58);
  cursor: pointer;
  font: inherit;
  font-size: clamp(11px, 1.45vw, 14px);
  letter-spacing: -0.05em;
  white-space: nowrap;
  transition: color 180ms ease;
}

.age-timeline__point::before {
  position: relative;
  z-index: 1;
  width: 11px;
  height: 11px;
  border: 1px solid rgba(240, 236, 226, 0.7);
  border-radius: 50%;
  background: rgba(26, 29, 33, 0.88);
  content: "";
  transition: background-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.age-timeline__point[aria-pressed="true"] {
  color: #fffdf7;
}

.age-timeline__point[aria-pressed="true"]::before {
  border-color: #f7f4ec;
  background: #f7f4ec;
  box-shadow: 0 0 0 5px rgba(247, 244, 236, 0.12);
  transform: scale(1.08);
}

.age-timeline__point:focus-visible {
  outline: 1px solid rgba(255, 255, 255, 0.84);
  outline-offset: 6px;
}

.question-block--depth {
  position: relative;
}

.knowledge-value {
  display: block;
  min-height: 24px;
  margin-top: 10px;
  color: #f4f1e9;
  font-size: clamp(15px, 1.9vw, 18px);
  font-weight: 500;
  letter-spacing: -0.045em;
}

.depth-slider {
  position: relative;
  height: 22px;
  margin-top: 7px;
}

.depth-slider__track {
  position: absolute;
  top: 10px;
  right: 0;
  left: 0;
  height: 1px;
  background: rgba(240, 236, 226, 0.34);
}

.depth-slider__fill {
  display: block;
  width: 0;
  height: 100%;
  background: #f5f2eb;
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.32);
}

.depth-slider__input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 22px;
  margin: 0;
  appearance: none;
  background: transparent;
  cursor: pointer;
}

.depth-slider__input::-webkit-slider-runnable-track {
  height: 22px;
  background: transparent;
}

.depth-slider__input::-moz-range-track {
  height: 22px;
  background: transparent;
}

.depth-slider__input::-webkit-slider-thumb {
  width: 13px;
  height: 13px;
  margin-top: 4.5px;
  appearance: none;
  border: 1px solid #fffdf7;
  border-radius: 50%;
  background: #f7f4ec;
  box-shadow: 0 0 0 4px rgba(247, 244, 236, 0.13);
}

.depth-slider__input::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border: 1px solid #fffdf7;
  border-radius: 50%;
  background: #f7f4ec;
  box-shadow: 0 0 0 4px rgba(247, 244, 236, 0.13);
}

.depth-slider__input:focus-visible {
  outline: 1px solid rgba(255, 255, 255, 0.7);
  outline-offset: 5px;
}

.depth-slider__captions {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 6px;
  color: rgba(239, 234, 221, 0.52);
  font-size: 11px;
  letter-spacing: -0.025em;
}

.question-submit {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 50px;
  margin-top: clamp(24px, 3.2vh, 30px);
  padding: 0 2px;
  border: 0;
  border-top: 1px solid rgba(245, 242, 232, 0.5);
  border-bottom: 1px solid rgba(245, 242, 232, 0.5);
  background: transparent;
  color: #f7f4ec;
  cursor: pointer;
  font: inherit;
  font-size: 15px;
  letter-spacing: -0.04em;
  text-align: left;
}

.question-submit__arrow {
  font-size: 22px;
  transition: transform 180ms ease;
}

.question-submit:hover .question-submit__arrow,
.question-submit:focus-visible .question-submit__arrow {
  transform: translateX(5px);
}

.question-submit:focus-visible {
  outline: 1px solid rgba(255, 255, 255, 0.84);
  outline-offset: 5px;
}

.question-status {
  min-height: 18px;
  margin: 8px 0 0;
  color: rgba(239, 234, 221, 0.76);
  font-size: 12px;
}

@keyframes question-panel-arrive {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 560px) {
  .question-screen {
    align-items: center;
    padding: max(16px, env(safe-area-inset-top)) 14px max(16px, env(safe-area-inset-bottom));
  }

  .question-panel {
    padding: 26px 20px 20px;
  }

  .question-header__eyebrow {
    margin-bottom: 16px;
    font-size: 9px;
  }

  .age-timeline {
    margin-top: 26px;
  }

  .age-timeline__point {
    font-size: clamp(9px, 2.8vw, 12px);
    letter-spacing: -0.07em;
  }

  .age-timeline::before {
    right: 12%;
    left: 12%;
  }
}

@media (max-height: 600px) {
  .question-screen {
    padding-top: 14px;
    padding-bottom: 14px;
  }

  .question-panel {
    padding-top: 24px;
    padding-bottom: 18px;
  }

  .question-header__eyebrow {
    margin-bottom: 12px;
  }

  .question-form {
    padding-top: 20px;
  }

  .question-block + .question-block {
    margin-top: 22px;
  }

  .question-submit {
    min-height: 46px;
    margin-top: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .question-panel,
  .age-timeline__point,
  .age-timeline__point::before,
  .question-submit__arrow {
    animation: none;
    transition: none;
  }
}
